        fn js_mol_chain_get_name(
            this: &JsValue,
            _args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            Ok(JsString::from(this_string_prop(this, "_chain_name", ctx)).into())
        }
        fn js_mol_chain_set_name(
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = object_number_prop(this, "parent_uid", ctx)? as u64;
            let old_name = this_string_prop(this, "_chain_name", ctx);
            let new_name = arg0(args, ctx);
            if uid == 0 {
                this.as_object()
                    .ok_or_else(|| script_error("MolChain receiver is not an object"))?
                    .set(
                        js_string!("_chain_name"),
                        JsString::from(new_name),
                        true,
                        ctx,
                    )?;
                return Ok(JsValue::undefined());
            }
            let changed = with_script_molecule_mut(uid, |molecule| {
                molecule.relabel_residue_keys(|atom| {
                    (atom.chain_id == old_name).then(|| {
                        cuemol_molstr::ResidueKey::new(new_name.clone(), atom.res_id, atom.ins_code)
                    })
                })
            })?;
            if !changed {
                return Err(script_error(
                    "Chain name change collides with another residue",
                ));
            }
            this.as_object()
                .ok_or_else(|| script_error("MolChain receiver is not an object"))?
                .set(
                    js_string!("_chain_name"),
                    JsString::from(new_name),
                    true,
                    ctx,
                )?;
            Ok(JsValue::undefined())
        }
        fn chain_summary_from_proxy(
            this: &JsValue,
            ctx: &mut Context,
        ) -> JsResult<(ScriptMol, cuemol_molstr::ChainSummary)> {
            let molecule = molecule_from_parent(this, ctx)?;
            let name = this_string_prop(this, "_chain_name", ctx);
            let summary = molecule
                .molecule
                .get_chain(&name)
                .ok_or_else(|| script_error("MolChain is not available"))?;
            Ok((molecule, summary))
        }
        fn js_mol_chain_resids_json(
            this: &JsValue,
            _args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            if object_number_prop(this, "parent_uid", ctx)? == 0.0 {
                return Ok(js_string!("[]").into());
            }
            let (molecule, summary) = chain_summary_from_proxy(this, ctx)?;
            let entries = summary
                .residue_keys
                .iter()
                .filter_map(|key| {
                    molecule
                        .molecule
                        .get_residue(&key.chain_id, &key.script_index())
                        .ok()
                        .flatten()
                })
                .map(|residue| {
                    format!(
                        "{{\"name\":{:?},\"single\":\"\",\"sel\":false,\"index\":{:?}}}",
                        residue.res_name,
                        residue.key.script_index()
                    )
                })
                .collect::<Vec<_>>()
                .join(",");
            Ok(JsString::from(format!("[{entries}]")).into())
        }
