        fn js_camera_vis_append(
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = args
                .first()
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_number(ctx)?;
            if !uid.is_finite() || uid < 0.0 {
                return Err(script_error("Camera visibility UID is out of range"));
            }
            camera_append_entry(
                this,
                uid as u64,
                args.get(1).is_none_or(JsValue::to_boolean),
                args.get(2).is_some_and(JsValue::to_boolean),
                ctx,
            )?;
            Ok(JsValue::undefined())
        }
        fn js_camera_vis_remove(
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = args
                .first()
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_number(ctx)? as u64;
            let size = camera_vis_size(this, ctx)?;
            let mut found = None;
            for index in 0..size {
                if camera_vis_entry(this, index, ctx)?.0 == uid {
                    found = Some(index);
                    break;
                }
            }
            let Some(index) = found else {
                return Ok(JsValue::new(false));
            };
            let object = iterator_object(this)?;
            for source in index + 1..size {
                let (entry_uid, visible, is_object) = camera_vis_entry(this, source, ctx)?;
                object.set(
                    camera_vis_key("uid", source - 1),
                    entry_uid as f64,
                    true,
                    ctx,
                )?;
                object.set(camera_vis_key("visible", source - 1), visible, true, ctx)?;
                object.set(camera_vis_key("object", source - 1), is_object, true, ctx)?;
            }
            object.set(js_string!("_vis_size"), size - 1, true, ctx)?;
            Ok(JsValue::new(true))
        }
