        fn js_camera_save_vis(
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            if args.first().is_none_or(JsValue::is_null_or_undefined) {
                return Err(script_error("Camera saveVisSettings requires a scene"));
            }
            js_camera_clear_vis(this, &[], ctx)?;
            let entries = script_env::with(|env| {
                env.objects
                    .iter()
                    .flat_map(|object| {
                        std::iter::once((object.uid, object.visible, true)).chain(
                            object
                                .renderers
                                .iter()
                                .map(|renderer| (renderer.uid, renderer.visible, false)),
                        )
                    })
                    .collect::<Vec<_>>()
            });
            for (uid, visible, is_object) in entries {
                camera_append_entry(this, uid, visible, is_object, ctx)?;
            }
            Ok(JsValue::undefined())
        }
        fn js_camera_load_vis(
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            if args.first().is_none_or(JsValue::is_null_or_undefined) {
                return Err(script_error("Camera loadVisSettings requires a scene"));
            }
            for index in 0..camera_vis_size(this, ctx)? {
                let (uid, visible, is_object) = camera_vis_entry(this, index, ctx)?;
                script_cmds::push(ScriptCmd::SetVisibilityByUid {
                    uid,
                    visible,
                    is_object,
                });
            }
            Ok(JsValue::undefined())
        }
