        fn view_uid(this: &JsValue, ctx: &mut Context) -> JsResult<Uid> {
            Ok(Uid::new(object_number_prop(this, "_uid", ctx)? as u64))
        }
        fn with_script_view<R>(
            this: &JsValue,
            ctx: &mut Context,
            operation: impl FnOnce(&cuemol_qsys::View) -> R,
        ) -> JsResult<R> {
            let uid = view_uid(this, ctx)?;
            script_env::with(|env| {
                env.views
                    .iter()
                    .find(|view| view.uid() == uid)
                    .map(operation)
            })
            .ok_or_else(|| script_error(format!("View {} is not available", uid.get())))
        }
        fn with_script_view_mut<R>(
            this: &JsValue,
            ctx: &mut Context,
            operation: impl FnOnce(&mut cuemol_qsys::View) -> R,
        ) -> JsResult<R> {
            let uid = view_uid(this, ctx)?;
            script_env::with_mut(|env| {
                env.views
                    .iter_mut()
                    .find(|view| view.uid() == uid)
                    .map(operation)
            })
            .ok_or_else(|| script_error(format!("View {} is not available", uid.get())))
        }
        fn stereo_mode_name(mode: cuemol_qsys::StereoMode) -> &'static str {
            match mode {
                cuemol_qsys::StereoMode::None => "none",
                cuemol_qsys::StereoMode::Parallel => "para",
                cuemol_qsys::StereoMode::Cross => "cross",
                cuemol_qsys::StereoMode::Hardware => "hardware",
            }
        }
        fn center_mark_name(mark: cuemol_qsys::CenterMark) -> &'static str {
            match mark {
                cuemol_qsys::CenterMark::None => "none",
                cuemol_qsys::CenterMark::Cross => "crosshair",
                cuemol_qsys::CenterMark::Axis => "axis",
            }
        }
        fn view_property_get(
            property: ViewProperty,
            this: &JsValue,
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            if matches!(
                property,
                ViewProperty::Center
                    | ViewProperty::UpVector
                    | ViewProperty::RightVector
                    | ViewProperty::ForwardVector
            ) {
                let vector = with_script_view(this, ctx, |view| match property {
                    ViewProperty::Center => view.center(),
                    ViewProperty::UpVector => view.up_vec(),
                    ViewProperty::RightVector => view.right_vec(),
                    ViewProperty::ForwardVector => view.forward_vec(),
                    _ => unreachable!(),
                })?;
                return Ok(make_vector(vector, ctx));
            }
            if matches!(property, ViewProperty::Rotation) {
                let rotation = with_script_view(this, ctx, cuemol_qsys::View::rotation)?;
                return Ok(make_quat(rotation, ctx));
            }
            with_script_view(this, ctx, |view| match property {
                ViewProperty::Name => JsString::from(view.name()).into(),
                ViewProperty::Active => JsValue::new(view.active()),
                ViewProperty::Zoom => JsValue::new(view.zoom()),
                ViewProperty::Distance => JsValue::new(view.distance()),
                ViewProperty::Slab => JsValue::new(view.slab()),
                ViewProperty::Perspective => JsValue::new(view.perspective()),
                ViewProperty::Width => JsValue::new(view.width()),
                ViewProperty::Height => JsValue::new(view.height()),
                ViewProperty::TransMms => JsValue::new(view.trans_mms()),
                ViewProperty::RotMms => JsValue::new(view.rot_mms()),
                ViewProperty::StereoMode => {
                    JsString::from(stereo_mode_name(view.stereo_mode())).into()
                }
                ViewProperty::HasHwStereo => JsValue::new(view.has_hw_stereo()),
                ViewProperty::StereoDist => JsValue::new(view.stereo_dist()),
                ViewProperty::SwapStereoEyes => JsValue::new(view.swap_stereo_eyes()),
                ViewProperty::CenterMark => {
                    JsString::from(center_mark_name(view.center_mark())).into()
                }
                ViewProperty::Style => JsString::from(view.style()).into(),
                ViewProperty::Center
                | ViewProperty::Rotation
                | ViewProperty::UpVector
                | ViewProperty::RightVector
                | ViewProperty::ForwardVector => unreachable!(),
            })
        }
        fn view_property_set(
            property: ViewProperty,
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let value = args.first().cloned().unwrap_or(JsValue::undefined());
            match property {
                ViewProperty::Name => {
                    let name = value.to_string(ctx)?.to_std_string_escaped();
                    with_script_view_mut(this, ctx, |view| view.set_name(name))?;
                }
                ViewProperty::Active => {
                    with_script_view_mut(this, ctx, |view| view.set_active(value.to_boolean()))?;
                }
                ViewProperty::Zoom => {
                    let number = value.to_number(ctx)?;
                    with_script_view_mut(this, ctx, |view| view.set_zoom(number))?;
                }
                ViewProperty::Distance => {
                    let number = value.to_number(ctx)?;
                    with_script_view_mut(this, ctx, |view| view.set_distance(number))?;
                }
                ViewProperty::Slab => {
                    let number = value.to_number(ctx)?;
                    with_script_view_mut(this, ctx, |view| view.set_slab(number))?;
                }
                ViewProperty::Center => {
                    let vector = vector_from_value(&value, ctx)?;
                    with_script_view_mut(this, ctx, |view| view.set_center(vector))?;
                }
                ViewProperty::Rotation => {
                    let rotation = quat_from_value(&value, ctx)?;
                    with_script_view_mut(this, ctx, |view| view.set_rotation(rotation))?;
                }
                ViewProperty::Perspective => {
                    with_script_view_mut(this, ctx, |view| {
                        view.set_perspective(value.to_boolean());
                    })?;
                }
                ViewProperty::TransMms => {
                    with_script_view_mut(this, ctx, |view| {
                        view.set_trans_mms(value.to_boolean());
                    })?;
                }
                ViewProperty::RotMms => {
                    with_script_view_mut(this, ctx, |view| view.set_rot_mms(value.to_boolean()))?;
                }
                ViewProperty::StereoMode => {
                    let name = value.to_string(ctx)?.to_std_string_escaped();
                    let mode = match name.as_str() {
                        "none" => cuemol_qsys::StereoMode::None,
                        "para" => cuemol_qsys::StereoMode::Parallel,
                        "cross" => cuemol_qsys::StereoMode::Cross,
                        "hardware" => cuemol_qsys::StereoMode::Hardware,
                        _ => {
                            return Err(script_error(format!("unknown View stereoMode {name}")));
                        }
                    };
                    with_script_view_mut(this, ctx, |view| view.set_stereo_mode(mode))?;
                }
                ViewProperty::StereoDist => {
                    let number = value.to_number(ctx)?;
                    with_script_view_mut(this, ctx, |view| view.set_stereo_dist(number))?;
                }
                ViewProperty::SwapStereoEyes => {
                    with_script_view_mut(this, ctx, |view| {
                        view.set_swap_stereo_eyes(value.to_boolean());
                    })?;
                }
                ViewProperty::CenterMark => {
                    let name = value.to_string(ctx)?.to_std_string_escaped();
                    let mark = match name.as_str() {
                        "none" => cuemol_qsys::CenterMark::None,
                        "crosshair" => cuemol_qsys::CenterMark::Cross,
                        "axis" => cuemol_qsys::CenterMark::Axis,
                        _ => {
                            return Err(script_error(format!("unknown View centerMark {name}")));
                        }
                    };
                    with_script_view_mut(this, ctx, |view| view.set_center_mark(mark))?;
                }
                ViewProperty::Width
                | ViewProperty::Height
                | ViewProperty::HasHwStereo
                | ViewProperty::UpVector
                | ViewProperty::RightVector
                | ViewProperty::ForwardVector
                | ViewProperty::Style => {
                    return Err(script_error("View property is read-only"));
                }
            }
            Ok(JsValue::undefined())
        }
