        fn make_camera_from_core(
            camera: &cuemol_qsys::Camera,
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let value = make_camera(ctx);
            let object = value
                .as_object()
                .ok_or_else(|| script_error("Camera proxy creation failed"))?;
            object.set(js_string!("name"), JsString::from(camera.name()), true, ctx)?;
            object.set(js_string!("_zoom"), camera.zoom(), true, ctx)?;
            object.set(js_string!("_slab"), camera.slab(), true, ctx)?;
            object.set(js_string!("_distance"), camera.distance(), true, ctx)?;
            object.set(
                js_string!("center"),
                make_vector(camera.center(), ctx),
                true,
                ctx,
            )?;
            object.set(
                js_string!("rotation"),
                make_quat(camera.rotation(), ctx),
                true,
                ctx,
            )?;
            object.set(
                js_string!("stereoMode"),
                JsString::from(stereo_mode_name(camera.stereo_mode())),
                true,
                ctx,
            )?;
            object.set(js_string!("stereoDist"), camera.stereo_dist(), true, ctx)?;
            object.set(js_string!("perspec"), camera.perspec(), true, ctx)?;
            object.set(
                js_string!("centerMark"),
                JsString::from(center_mark_name(camera.center_mark())),
                true,
                ctx,
            )?;
            Ok(value)
        }
