        fn js_view_hit_test_polygon(
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let bytes = byte_array_from_value(args.first().unwrap_or(&JsValue::undefined()), ctx)?;
            if bytes.elem_type_code() != ByteArray::FLOAT32 || bytes.elem_count() % 2 != 0 {
                return Err(script_error(
                    "hitTestPolygon requires paired FLOAT32 coordinates",
                ));
            }
            let mut points = Vec::with_capacity(bytes.elem_count() / 2);
            for index in (0..bytes.elem_count()).step_by(2) {
                let x = bytes
                    .get_at_f(index)
                    .map_err(|error| script_error(error.to_string()))?;
                let y = bytes
                    .get_at_f(index + 1)
                    .map_err(|error| script_error(error.to_string()))?;
                points.push((x, y));
            }
            let nearest = args.get(1).is_some_and(JsValue::to_boolean);
            with_script_view(this, ctx, |view| {
                JsString::from(view.hit_test_polygon(&points, nearest)).into()
            })
        }
