        fn js_object_get_residue(
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = object_number_prop(this, "uid", ctx)? as u64;
            let chain = arg0(args, ctx);
            let index_text = argn(args, 1, ctx);
            let index = cuemol_molstr::ResidIndex::parse(&index_text)
                .map_err(|error| script_error(error.to_string()))?;
            let residue = script_env::with(|env| {
                env.molecules
                    .iter()
                    .find(|entry| entry.uid == uid)
                    .and_then(|entry| {
                        entry
                            .molecule
                            .residue_summaries()
                            .into_iter()
                            .find(|residue| {
                                residue.key.chain_id == chain
                                    && residue.key.res_id == index.number
                                    && residue.key.ins_code == index.ins_code
                            })
                    })
            });
            let Some(residue) = residue else {
                return Ok(JsValue::null());
            };
            Ok(make_mol_residue(uid, &residue, ctx))
        }
