        #[derive(Clone, Copy)]
        enum MorphProperty {
            Frame,
            ScaleFrame,
            FrameCount,
        }
        fn install_morph_property(
            value: &JsValue,
            name: &'static str,
            property: MorphProperty,
            writable: bool,
            ctx: &mut Context,
        ) {
            let Some(object) = value.as_object() else {
                return;
            };
            let getter = FunctionObjectBuilder::new(
                ctx.realm(),
                NativeFunction::from_copy_closure(move |this, args, ctx| {
                    morph_property_get(property, this, args, ctx)
                }),
            )
            .name(JsString::from(format!("get {name}")))
            .length(0)
            .constructor(false)
            .build();
            let setter = writable.then(|| {
                FunctionObjectBuilder::new(
                    ctx.realm(),
                    NativeFunction::from_copy_closure(move |this, args, ctx| {
                        morph_property_set(property, this, args, ctx)
                    }),
                )
                .name(JsString::from(format!("set {name}")))
                .length(1)
                .constructor(false)
                .build()
            });
            let _ = object.define_property_or_throw(
                JsString::from(name),
                PropertyDescriptor::builder()
                    .get(getter)
                    .maybe_set(setter)
                    .enumerable(true)
                    .configurable(true),
                ctx,
            );
        }
        fn morph_property_get(
            property: MorphProperty,
            this: &JsValue,
            _args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = object_proxy_uid(this, ctx)?;
            let morph = script_env::with(|env| env.morphs.get(&uid).cloned())
                .ok_or_else(|| script_error(format!("MorphMol {uid} is not available")))?;
            Ok(match property {
                MorphProperty::Frame => JsValue::new(morph.frame()),
                MorphProperty::ScaleFrame => JsValue::new(morph.scale_frame()),
                MorphProperty::FrameCount => JsValue::new(morph.frame_size() as f64),
            })
        }
        fn morph_property_set(
            property: MorphProperty,
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = object_proxy_uid(this, ctx)?;
            let value = args.first().cloned().unwrap_or(JsValue::undefined());
            match property {
                MorphProperty::Frame => {
                    let frame = value.to_number(ctx)?;
                    apply_script_morph_frame(uid, frame)?;
                }
                MorphProperty::ScaleFrame => {
                    let scale = value.to_boolean();
                    script_env::with_mut(|env| {
                        env.morphs
                            .get_mut(&uid)
                            .map(|morph| morph.set_scale_frame(scale))
                    })
                    .ok_or_else(|| script_error(format!("MorphMol {uid} is not available")))?;
                }
                MorphProperty::FrameCount => {
                    return Err(script_error("MorphMol nframe is read-only"));
                }
            }
            Ok(JsValue::undefined())
        }
        fn js_morph_insert_before(
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = object_proxy_uid(this, ctx)?;
            let source_uid =
                object_proxy_uid(&args.first().cloned().unwrap_or(JsValue::undefined()), ctx)?;
            let index = args
                .get(1)
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_i32(ctx)?;
            let source_value = args.first().cloned().unwrap_or(JsValue::undefined());
            let source = script_env::with(|env| {
                Some(
                    env.molecules
                        .iter()
                        .find(|molecule| molecule.uid == source_uid)?
                        .molecule
                        .clone(),
                )
            })
            .ok_or_else(|| script_error("MorphMol source is not available"))?;
            let positions = script_env::with(|env| {
                env.morphs
                    .get(&uid)
                    .map(|morph| morph.positions_for_molecule(&source))
            })
            .ok_or_else(|| script_error(format!("MorphMol {uid} is not available")))?;
            let frame = MorphFrame::new(
                object_string_prop(&source_value, "name", ctx),
                object_string_prop(&source_value, "src", ctx),
                object_string_prop(&source_value, "srctype", ctx),
                positions,
            );
            script_env::with_mut(|env| {
                env.morphs.get_mut(&uid).map(|morph| {
                    morph.insert_frame_before(
                        frame,
                        if index < 0 {
                            usize::MAX
                        } else {
                            index as usize
                        },
                    )
                })
            })
            .ok_or_else(|| script_error(format!("MorphMol {uid} is not available")))?;
            Ok(JsValue::undefined())
        }
        fn js_morph_remove_frame(
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = object_proxy_uid(this, ctx)?;
            let index = args
                .first()
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_i32(ctx)?;
            if index >= 0 {
                script_env::with_mut(|env| {
                    env.morphs
                        .get_mut(&uid)
                        .map(|morph| morph.remove_frame(index as usize))
                })
                .ok_or_else(|| script_error(format!("MorphMol {uid} is not available")))?;
            }
            Ok(JsValue::undefined())
        }
        fn js_morph_frame_info(
            this: &JsValue,
            _args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = object_proxy_uid(this, ctx)?;
            script_env::with(|env| {
                env.morphs
                    .get(&uid)
                    .map(|morph| JsString::from(morph.frame_info_json()).into())
            })
            .ok_or_else(|| script_error(format!("MorphMol {uid} is not available")))
        }
        fn js_morph_append_this_frame(
            this: &JsValue,
            _args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = object_proxy_uid(this, ctx)?;
            let molecule = script_env::with(|env| {
                env.molecules
                    .iter()
                    .find(|molecule| molecule.uid == uid)
                    .map(|molecule| molecule.molecule.clone())
            })
            .ok_or_else(|| script_error(format!("Molecule {uid} is not available")))?;
            script_env::with_mut(|env| {
                env.morphs.get_mut(&uid).map(|morph| {
                    *morph.molecule_mut() = molecule;
                    morph.append_this_frame()
                })
            })
            .ok_or_else(|| script_error(format!("MorphMol {uid} is not available")))?;
            Ok(JsValue::undefined())
        }
