        fn pending_renderer_base_attributes(
            value: &JsValue,
            ctx: &mut Context,
        ) -> JsResult<BTreeMap<String, String>> {
            let object = value
                .as_object()
                .ok_or_else(|| script_error("renderer value is not an object"))?;
            let mut attributes = BTreeMap::new();
            attributes.insert(
                "locked".to_string(),
                object
                    .get(js_string!("locked"), ctx)?
                    .to_boolean()
                    .to_string(),
            );
            for name in ["style", "material", "group", "egtype"] {
                attributes.insert(
                    name.to_string(),
                    object
                        .get(JsString::from(name), ctx)?
                        .to_string(ctx)?
                        .to_std_string_escaped(),
                );
            }
            attributes.insert(
                "alpha".to_string(),
                object
                    .get(js_string!("alpha"), ctx)?
                    .to_number(ctx)?
                    .to_string(),
            );
            attributes.insert(
                "xformMat".to_string(),
                matrix_from_value(&object.get(js_string!("xformMat"), ctx)?, ctx)?
                    .to_script_string(),
            );
            attributes.insert(
                "ui_order".to_string(),
                object
                    .get(js_string!("ui_order"), ctx)?
                    .to_i32(ctx)?
                    .to_string(),
            );
            attributes.insert(
                "eglinew".to_string(),
                object
                    .get(js_string!("eglinew"), ctx)?
                    .to_number(ctx)?
                    .to_string(),
            );
            attributes.insert(
                "egcolor".to_string(),
                solid_color_from_script_value(&object.get(js_string!("egcolor"), ctx)?, ctx)?
                    .script_string(),
            );
            Ok(attributes)
        }
        fn pending_renderer_is_compatible(
            this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let value = args.first().cloned().unwrap_or(JsValue::undefined());
            let class_name = object_optional_string_prop(&value, "_class", ctx)
                .filter(|value| !value.is_empty())
                .or_else(|| object_optional_string_prop(&value, "type", ctx))
                .unwrap_or_default();
            Ok(JsValue::new(renderer_compatible_with_class(
                &this_string_prop(this, "_renderer_type", ctx),
                &class_name,
            )))
        }
