        fn js_renderer_get_center(
            this: &JsValue,
            _args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let renderer = script_renderer(renderer_proxy_uid(this, ctx)?)?;
            if is_map_renderer_type(&renderer.rtype) {
                let center = renderer
                    .attributes
                    .get("center")
                    .and_then(|value| Vector4::from_script_string(value).ok())
                    .unwrap_or(Vector4::ZERO);
                return Ok(make_vector(center, ctx));
            }
            let center = script_env::with(|env| {
                env.molecules
                    .iter()
                    .find(|molecule| molecule.uid == renderer.object_uid)
                    .and_then(|molecule| molecule.molecule.center_pos(None))
            });
            Ok(center
                .map(|value| make_vector(value, ctx))
                .unwrap_or_else(JsValue::null))
        }
