        fn make_scene_proxy(ctx: &mut Context) -> JsValue {
            let scene_uid = script_env::with(|env| env.scene_uid);
            make_scene_proxy_for(scene_uid, ctx)
        }
        fn js_get_scene(_t: &JsValue, args: &[JsValue], ctx: &mut Context) -> JsResult<JsValue> {
            if let Some(value) = args.first() {
                let uid = value.to_number(ctx)? as u64;
                if !script_env::with(|env| env.scenes.iter().any(|scene| scene.uid == uid)) {
                    return Ok(JsValue::null());
                }
                return Ok(make_scene_proxy_for(uid, ctx));
            }
            Ok(make_scene_proxy(ctx))
        }
        fn js_get_uid_object(
            _t: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = args
                .first()
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_number(ctx)? as u64;
            if script_env::with(|env| env.scenes.iter().any(|scene| scene.uid == uid)) {
                return Ok(make_scene_proxy_for(uid, ctx));
            }
            let object = script_env::with(|env| {
                env.objects.iter().find(|object| object.uid == uid).cloned()
            });
            if let Some(object) = object {
                return Ok(make_object_proxy(object, ctx));
            }
            if script_env::with(|env| env.views.iter().any(|view| view.uid().get() == uid)) {
                return Ok(make_view_proxy(Uid::new(uid), ctx));
            }
            let renderer = script_env::with(|env| {
                env.objects.iter().find_map(|object| {
                    object
                        .renderers
                        .iter()
                        .find(|renderer| renderer.uid == uid)
                        .cloned()
                        .map(|renderer| (object.name.clone(), renderer))
                })
            });
            Ok(renderer
                .map(|(name, renderer)| make_renderer_proxy(&name, renderer, ctx))
                .unwrap_or_else(JsValue::null))
        }
        fn js_scene_manager_get_scene(
            _t: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = args
                .first()
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_number(ctx)? as u64;
            let matches = script_env::with(|env| env.scenes.iter().any(|scene| scene.uid == uid));
            Ok(if matches {
                make_scene_proxy_for(uid, ctx)
            } else {
                JsValue::null()
            })
        }
        fn js_scene_manager_get_scene_by_name(
            _this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let name = arg0(args, ctx);
            let uid = script_env::with(|env| {
                env.scenes
                    .iter()
                    .find(|scene| scene.name == name)
                    .map(|scene| scene.uid)
            });
            Ok(uid
                .map(|uid| make_scene_proxy_for(uid, ctx))
                .unwrap_or_else(JsValue::null))
        }
        fn js_scene_manager_create_scene(
            _this: &JsValue,
            _args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = script_env::with_mut(|env| {
                let uid = env.next_scene_uid;
                env.next_scene_uid = env.next_scene_uid.saturating_add(1);
                env.scenes.push(ScriptSceneInfo {
                    uid,
                    name: String::new(),
                    attributes: BTreeMap::new(),
                    active_object_uid: None,
                    active_renderer_uid: None,
                    active_view_uid: None,
                    cameras: Vec::new(),
                    animation: AnimMgr::new(),
                    qsc_options: None,
                    next_object_uid: cuemol_molstr::MolScene::first_object_uid(Uid::new(uid)).get(),
                    undo_descriptions: Vec::new(),
                    redo_descriptions: Vec::new(),
                    undo_active: None,
                });
                uid
            });
            script_cmds::push(ScriptCmd::CreateScene {
                expected_uid: uid,
                name: String::new(),
                create_view: false,
                activate: false,
            });
            Ok(make_scene_proxy_for(uid, ctx))
        }
        fn js_scene_manager_destroy_scene(
            _this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = args
                .first()
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_number(ctx)? as u64;
            let removed = script_env::with_mut(|env| {
                let before = env.scenes.len();
                env.scenes.retain(|scene| scene.uid != uid);
                if env.scene_uid == uid {
                    env.scene_uid = 0;
                    env.scene_name.clear();
                    env.scene_attributes.clear();
                    env.cameras.clear();
                    env.animation = AnimMgr::new();
                }
                before != env.scenes.len()
            });
            if removed {
                script_cmds::push(ScriptCmd::DestroyScene { uid });
            }
            Ok(JsValue::new(removed))
        }
        fn js_scene_manager_destroy_all(
            _this: &JsValue,
            _args: &[JsValue],
            _ctx: &mut Context,
        ) -> JsResult<JsValue> {
            script_env::with_mut(|env| {
                env.scenes.clear();
                env.scene_uid = 0;
                env.scene_name.clear();
                env.scene_attributes.clear();
                env.objects.clear();
                env.molecules.clear();
                env.cameras.clear();
                env.animation = AnimMgr::new();
                env.views.clear();
            });
            script_cmds::push(ScriptCmd::DestroyAllScenes);
            Ok(JsValue::undefined())
        }
