        fn js_scene_manager_set_active_scene(
            _this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let uid = args
                .first()
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_number(ctx)? as u64;
            let selected = script_env::with_mut(|env| {
                if let Some(current) = env
                    .scenes
                    .iter_mut()
                    .find(|scene| scene.uid == env.scene_uid)
                {
                    current.name = env.scene_name.clone();
                    current.attributes = env.scene_attributes.clone();
                    current.cameras = env.cameras.clone();
                    current.animation = env.animation.clone();
                }
                let scene = env.scenes.iter().find(|scene| scene.uid == uid)?.clone();
                env.scene_uid = uid;
                env.scene_name = scene.name;
                env.scene_attributes = scene.attributes;
                env.cameras = scene.cameras;
                env.animation = scene.animation;
                Some(())
            });
            if selected.is_none() {
                return Err(script_error(format!("unknown scene UID {uid}")));
            }
            script_cmds::push(ScriptCmd::SetActiveScene { uid });
            Ok(JsValue::undefined())
        }
        fn js_scene_manager_check_updates(
            _this: &JsValue,
            _args: &[JsValue],
            _ctx: &mut Context,
        ) -> JsResult<JsValue> {
            script_env::with_mut(|env| {
                for view in &mut env.views {
                    view.check_and_update();
                }
            });
            Ok(JsValue::undefined())
        }
        fn js_scene_manager_dump(
            _this: &JsValue,
            _args: &[JsValue],
            _ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let dump = script_env::with(|env| {
                let scenes = env
                    .scenes
                    .iter()
                    .map(|scene| format!("  Scene({}, {})", scene.uid, scene.name))
                    .collect::<Vec<_>>()
                    .join("\n");
                format!("SCENE DUMP:\nSceneManager : {{\n{scenes}\n}}\nSCENEMANAGER DUMP END.")
            });
            script_cmds::push(ScriptCmd::Print(dump));
            Ok(JsValue::undefined())
        }
        fn js_scene_manager_enable_perf(
            _this: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let timer_id = args
                .first()
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_i32(ctx)?;
            cuemol_core::global_perf_manager()
                .lock()
                .map_err(|_| script_error("performance manager lock poisoned"))?
                .enable(timer_id);
            Ok(JsValue::undefined())
        }
        fn js_scene_manager_disable_perf(
            _this: &JsValue,
            _args: &[JsValue],
            _ctx: &mut Context,
        ) -> JsResult<JsValue> {
            cuemol_core::global_perf_manager()
                .lock()
                .map_err(|_| script_error("performance manager lock poisoned"))?
                .disable();
            Ok(JsValue::undefined())
        }
