        fn js_stream_search_reader(
            _t: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let path = arg0(args, ctx);
            let nicknames = argn(args, 1, ctx);
            let category_code = args
                .get(2)
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_i32(ctx)?;
            let category = cuemol_molstr::HandlerCategory::from_code(category_code)
                .map_err(|error| script_error(error.to_string()))?;
            let compressed = args.get(3).is_some_and(JsValue::to_boolean);
            let max_bytes = args
                .get(4)
                .cloned()
                .unwrap_or(JsValue::undefined())
                .to_number(ctx)? as u64;
            let found = StreamManager::new()
                .search_reader_by_content(path, &nicknames, category, compressed, max_bytes);
            Ok(JsString::from(found).into())
        }
