        fn js_symm_change_xtal_info(
            _t: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            if args.len() != 8 {
                return Err(script_error("changeXtalInfo: invalid arguments"));
            }
            script_cmds::push(ScriptCmd::ChangeCrystalInfo {
                object_uid: args[0].to_number(ctx)? as u64,
                a: args[1].to_number(ctx)?,
                b: args[2].to_number(ctx)?,
                c: args[3].to_number(ctx)?,
                alpha: args[4].to_number(ctx)?,
                beta: args[5].to_number(ctx)?,
                gamma: args[6].to_number(ctx)?,
                nsg: args[7].to_i32(ctx)?,
            });
            Ok(JsValue::undefined())
        }
        fn js_molanl_superpose_ssm1(
            _t: &JsValue,
            args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            let reference_value = args.first().cloned().unwrap_or(JsValue::undefined());
            let reference = script_molecule(&reference_value, ctx)?;
            let reference_selection = selector_from_script_value(
                &args.get(1).cloned().unwrap_or(JsValue::undefined()),
                ctx,
            )?;
            let moving_value = args.get(2).cloned().unwrap_or(JsValue::undefined());
            let moving = script_molecule(&moving_value, ctx)?;
            let moving_selection = selector_from_script_value(
                &args.get(3).cloned().unwrap_or(JsValue::undefined()),
                ctx,
            )?;
            let use_property = args.get(4).is_some_and(JsValue::to_boolean);
            let matrix = MolAnlManager::new()
                .superpose_ssm_matrix(
                    &reference.molecule,
                    &reference_selection,
                    &moving.molecule,
                    &moving_selection,
                )
                .map_err(|error| script_error(error.to_string()))?;
            if !use_property {
                script_cmds::push(ScriptCmd::ApplyMoleculeMatrix {
                    object_uid: moving.uid,
                    matrix,
                });
            }
            Ok(make_matrix(matrix, ctx))
        }
