        fn js_scene_manager_service(
            this: &JsValue,
            _args: &[JsValue],
            ctx: &mut Context,
        ) -> JsResult<JsValue> {
            js_get_service(this, &[JsString::from("SceneManager").into()], ctx)
        }
        fn js_exec(_t: &JsValue, args: &[JsValue], ctx: &mut Context) -> JsResult<JsValue> {
            let path = arg0(args, ctx);
            let source = Source::from_filepath(Path::new(&path))
                .map_err(|error| script_error(format!("execFile({path}) failed: {error}")))?;
            ctx.eval(source)
        }
        fn js_call_gc(_t: &JsValue, args: &[JsValue], _ctx: &mut Context) -> JsResult<JsValue> {
            if !args.is_empty() {
                return Err(script_error("callGC: invalid arguments"));
            }
            boa_engine::gc::force_collect();
            Ok(JsValue::undefined())
        }
        fn js_get_all_class_names_json(
            _t: &JsValue,
            args: &[JsValue],
            _ctx: &mut Context,
        ) -> JsResult<JsValue> {
            if !args.is_empty() {
                return Err(script_error("getAllClassNamesJSON: invalid arguments"));
            }
            let names = SCRIPT_RUNTIME_CLASS_NAMES
                .iter()
                .map(|name| format!("\"{name}\""))
                .collect::<Vec<_>>()
                .join(",");
            Ok(JsString::from(format!("[{names}]")).into())
        }
        fn js_get_cmd_args(_t: &JsValue, args: &[JsValue], ctx: &mut Context) -> JsResult<JsValue> {
            if args.len() != 1 {
                return Err(script_error("getCmdArgs: invalid argument 0"));
            }
            let _index = args[0].to_i32(ctx)?;
            // The desktop script action does not inject command-line arguments.
            Ok(JsValue::new(0))
        }
        // Live computed query: measure a selection (2 atoms→distance, 3→angle,
        // 4→torsion) against the snapshot molecules DURING eval — the same math as the
        // Measure ribbon, so a script can read a measurement programmatically.
        fn js_measure(_t: &JsValue, args: &[JsValue], ctx: &mut Context) -> JsResult<JsValue> {
            let sel = arg0(args, ctx);
            let result = script_env::with(|env| {
                let selector = parse_gui_selector(&sel).ok().flatten()?;
                let mut points = Vec::new();
                for entry in env
                    .molecules
                    .iter()
                    .filter(|entry| entry.scene_uid == env.scene_uid)
                {
                    let mol = &entry.molecule;
                    let atoms = mol.atoms();
                    for index in mol.select_indices(&selector) {
                        if let Some(atom) = atoms.get(index) {
                            points.push(atom.position);
                        }
                    }
                }
                measure_points(&points)
            });
            match result {
                Some(text) => Ok(JsString::from(text.as_str()).into()),
                None => Ok(JsValue::null()),
            }
        }

