    #[cfg(feature = "scripting")]
    #[test]
    fn run_script_js_detached_morph_mol_preserves_frames_when_attached() {
        let path =
            std::env::temp_dir().join(format!("cuemol-detached-morph-{}.pdb", std::process::id()));
        std::fs::write(
            &path,
            "ATOM      1  CA  GLY A   1       1.000   2.000   3.000  1.00 10.00           C  \nEND\n",
        )
        .unwrap();
        let mut app = DesktopAppState::new();
        let scene_uid = app.new_scene("detached-morph", true).result_scene;
        let source = format!(
            "var reader = cuemol.PDBFileReader(); \
             var source = reader.createDefaultObj(); reader.attach(source); \
             reader.setPath({path:?}); reader.read(); source.name = 'source'; \
             var morph = cuemol.MorphMol(); morph.name = 'morph'; \
             morph.copyAtoms(source, cuemol.makeSel('*')); morph.appendThisFrame(); \
             source.getAtomByID(1).pos = cuemol.createObj('Vector', '(9,2,3)'); \
             morph.insertBefore(source, -1); morph.scale_frame = true; morph.frame = 1; \
             print('detachedMorph=' + morph.nframe + ':' + morph.scale_frame + ':' + \
                   morph.getAtomByID(1).pos.x); \
             scene.addObject(morph); \
             print('attachedMorph=' + morph.nframe + ':' + morph.getScene().uid);",
            path = path.to_string_lossy(),
        );
        let result = app.run_script_js(&source);
        let _ = std::fs::remove_file(&path);
        let (log, _) = result.unwrap();
        assert!(
            log.contains("detachedMorph=2:true:9")
                && log.contains(&format!("attachedMorph=2:{}", scene_uid.get())),
            "{log:?}"
        );
        let object_uid = app
            .scene_manager()
            .scene(scene_uid)
            .unwrap()
            .object_by_name("morph")
            .unwrap()
            .uid();
        assert_eq!(app.morphs[&object_uid].frame_size(), 2);
        assert_eq!(
            app.scene_manager()
                .object(object_uid)
                .unwrap()
                .mol()
                .get_atom_by_id(1)
                .unwrap()
                .position
                .x,
            9.0
        );
    }

    #[cfg(feature = "scripting")]
    #[test]
    fn run_script_js_reports_renderer_runtime_classes_and_inheritance() {
        let mut app = DesktopAppState::new();
        let created = app.new_scene("renderer-classes", true);
        let molecule = cuemol_molstr::read_pdb_str(
            "CRYST1   10.000   10.000   10.000  90.00  90.00  90.00 P 1           1\n\
             ATOM      1  CA  GLY A   1       0.000   0.000   0.000  1.00 10.00           C  \n\
             END\n",
        )
        .expect("renderer test molecule parses");
        let object_uid = app
            .scene_manager_mut()
            .scene_mut(created.result_scene)
            .expect("scene exists")
            .add_molecule("mol", molecule);
        let mut renderers = BTreeMap::new();
        for renderer_type in [
            "simple",
            "anisou",
            "ribbon",
            "nucl",
            "atomintr",
            "directsurf",
        ] {
            let uid = app
                .new_renderer(
                    created.result_scene,
                    object_uid,
                    renderer_type,
                    renderer_type,
                )
                .expect("renderer is created")
                .result_renderer;
            renderers.insert(renderer_type, uid);
        }
        let (log, _) = app
            .run_script_js(&format!(
                "var simple = cuemol.getRenderer({simple}); \
                 var anisou = cuemol.getRenderer({anisou}); \
                 var ribbon = cuemol.getRenderer({ribbon}); \
                 var nucl = cuemol.getRenderer({nucl}); \
                 var atomintr = cuemol.getRenderer({atomintr}); \
                 var surface = cuemol.getRenderer({surface}); \
                 simple.width = 2.5; simple.valbond = false; simple.sel = cuemol.makeSel('name CA'); \
                 simple.defaultcolor = cuemol.makeColor('green'); \
                 anisou.bondw = 0.4; anisou.drawdisc = false; \
                 ribbon.axialdetail = 9; ribbon.helix_smooth = 1.25; \
                 ribbon.helix.width = 0.9; ribbon.helix.type = 'rectangle'; \
                 ribbon.helixhead.type = 'arrow'; ribbon.helixhead.gamma = 3; \
                 nucl.show_basepair = false; nucl.base_size = 0.75; nucl.section.tuber = 0.6; \
                 atomintr.stipple2 = 3; atomintr.color = cuemol.makeColor('blue'); \
                 surface.proberad = 1.8; surface.ramp_above = true; \
                 var rainbow = cuemol.RainbowColoring(); rainbow.start_hue = 180; \
                 simple.coloring = rainbow; simple.coloring.end_hue = 20; \
                 var paint = cuemol.PaintColoring(); \
                 paint.append(cuemol.makeSel('name CA'), cuemol.makeColor('red')); \
                 surface.coloring = paint; \
                 surface.coloring.append(cuemol.makeSel('name N'), cuemol.makeColor('blue')); \
                 var standaloneSection = cuemol.TubeSection(); \
                 var standaloneJunction = cuemol.JctTable(); \
                 print('rendererClasses=' + cuemol.getClassName(simple) + ':' + \
                       cuemol.getClassName(anisou) + ':' + cuemol.getClassName(ribbon) + ':' + \
                       cuemol.getClassName(nucl) + ':' + cuemol.getClassName(atomintr) + ':' + \
                       cuemol.getClassName(surface)); \
                 print('rendererIfaces=' + cuemol.implIface2(simple, 'MolRenderer') + ':' + \
                       cuemol.implIface2(anisou, 'BallStickRenderer') + ':' + \
                       cuemol.implIface2(ribbon, 'SplineRenderer') + ':' + \
                       cuemol.implIface2(nucl, 'TubeRenderer') + ':' + \
                       cuemol.implIface2(atomintr, 'Renderer') + ':' + \
                       cuemol.implIface2(surface, 'MolRenderer')); \
                 print('rendererProps=' + simple.width + ':' + simple.valbond + ':' + simple.sel + ':' + \
                       simple.defaultcolor.g() + ':' + anisou.bondw + ':' + anisou.drawdisc + ':' + \
                       ribbon.axialdetail + ':' + ribbon.helix_smooth + ':' + \
                       nucl.show_basepair + ':' + nucl.base_size + ':' + \
                       atomintr.stipple2 + ':' + atomintr.color.b() + ':' + \
                       surface.proberad + ':' + surface.ramp_above); \
                 print('rendererChildren=' + cuemol.getClassName(ribbon.helix) + ':' + \
                       ribbon.helix.width + ':' + ribbon.helix.type + ':' + \
                       cuemol.getClassName(ribbon.helixhead) + ':' + ribbon.helixhead.type + ':' + \
                       ribbon.helixhead.gamma + ':' + nucl.section.tuber + ':' + \
                       cuemol.getClassName(standaloneSection) + ':' + standaloneSection.width + ':' + \
                       cuemol.getClassName(standaloneJunction) + ':' + standaloneJunction.arrow); \
                 print('rendererColoring=' + cuemol.getClassName(simple.coloring) + ':' + \
                       cuemol.implIface2(simple.coloring, 'ColoringScheme') + ':' + \
                       simple.coloring.start_hue + ':' + simple.coloring.end_hue + ':' + \
                       cuemol.getClassName(surface.coloring) + ':' + surface.coloring.size + ':' + \
                       surface.coloring.getSelAt(0) + ':' + surface.coloring.getColorAt(0).r());",
                simple = renderers["simple"].get(),
                anisou = renderers["anisou"].get(),
                ribbon = renderers["ribbon"].get(),
                nucl = renderers["nucl"].get(),
                atomintr = renderers["atomintr"].get(),
                surface = renderers["directsurf"].get(),
            ))
            .expect("renderer runtime classes are queryable");
        assert!(
            log.contains(
                "rendererClasses=SimpleRenderer:AnIsoURenderer:RibbonRenderer:NARenderer:AtomIntrRenderer:DirectSurfRenderer"
            ) && log.contains("rendererIfaces=true:true:true:true:true:true")
                && log.contains(
                    "rendererProps=2.5:false:name CA:128:0.4:false:9:1.25:false:0.75:3:255:1.8:true"
                )
                && log.contains(
                    "rendererChildren=TubeSection:0.9:rectangle:JctTable:arrow:3:0.6:TubeSection:0.35:JctTable:1.8"
                )
                && log.contains(
                    "rendererColoring=RainbowColoring:true:180:20:PaintColoring:2:name CA:255"
                ),
            "{log:?}"
        );
        let object = app
            .scene_manager()
            .object(object_uid)
            .expect("renderer object remains available");
        assert_eq!(
            object
                .renderer(renderers["simple"])
                .and_then(|renderer| renderer.qsc_attr("sel")),
            Some("name CA")
        );
        assert_eq!(
            object
                .renderer(renderers["directsurf"])
                .and_then(|renderer| renderer.qsc_attr("ramp_above")),
            Some("true")
        );
        let ribbon = object
            .renderer(renderers["ribbon"])
            .expect("ribbon renderer remains available");
        assert_eq!(
            ribbon
                .qsc_children()
                .iter()
                .find(|node| node.tag_name() == "helix")
                .map(|node| node.str_attr("width").to_string()),
            Some("0.9".to_string())
        );
        let simple = object
            .renderer(renderers["simple"])
            .expect("simple renderer remains available");
        assert_eq!(
            simple
                .qsc_children()
                .iter()
                .find(|node| node.tag_name() == "coloring")
                .map(|node| (
                    node.type_name().to_string(),
                    node.str_attr("start_hue").to_string(),
                    node.str_attr("end_hue").to_string(),
                )),
            Some((
                "RainbowColoring".to_string(),
                "180".to_string(),
                "20".to_string(),
            ))
        );
        let surface = object
            .renderer(renderers["directsurf"])
            .expect("surface renderer remains available");
        assert_eq!(
            surface
                .qsc_children()
                .iter()
                .find(|node| node.tag_name() == "coloring")
                .map(|node| node
                    .children()
                    .iter()
                    .filter(|child| child.tag_name() == "paint")
                    .count()),
            Some(2)
        );

        let path =
            std::env::temp_dir().join(format!("cuemol-renderer-qif-{}.qsc", std::process::id()));
        app.save_active_scene_qsc(&path)
            .expect("renderer coloring scene is saved");
        let saved = std::fs::read_to_string(&path).expect("renderer QSC is readable");
        assert!(saved.contains("<coloring type=\"RainbowColoring\""));
        assert!(saved.contains("<coloring type=\"PaintColoring\">"));
        let mut reloaded = DesktopAppState::new();
        let reloaded_scene = reloaded
            .load_qsc_file(&path)
            .expect("renderer QSC reload succeeds")
            .expect("renderer QSC scene exists");
        let reloaded_object = reloaded
            .scene_manager()
            .scene(reloaded_scene)
            .and_then(|scene| scene.object_by_name("mol"))
            .expect("reloaded renderer object exists");
        let reloaded_surface = reloaded_object
            .renderer_by_name("directsurf")
            .expect("reloaded surface renderer exists");
        assert_eq!(
            reloaded_surface
                .qsc_children()
                .iter()
                .find(|child| child.tag_name() == "coloring")
                .map(|child| child.type_name()),
            Some("PaintColoring")
        );
        let (reload_log, _) = reloaded
            .run_script_js(
                "var simple = cuemol.getRenderer('mol', 'simple'); \
                 var surface = cuemol.getRenderer('mol', 'directsurf'); \
                 print('rendererColoringReload=' + simple.coloring.start_hue + ':' + \
                       simple.coloring.end_hue + ':' + surface.coloring.size + ':' + \
                       surface.coloring.getSelAt(1));",
            )
            .expect("reloaded renderer colorings are scriptable");
        assert!(
            reload_log.contains("rendererColoringReload=180:20:2:name N"),
            "{reload_log:?}"
        );
        let _ = std::fs::remove_file(path);
    }

    #[cfg(feature = "scripting")]
    #[test]
    fn run_script_js_exposes_remaining_renderer_qif_properties_and_label_methods() {
        let mut app = DesktopAppState::new();
        let created = app.new_scene("renderer-extra-qif", true);
        let molecule = cuemol_molstr::read_pdb_str(
            "CRYST1   10.000   10.000   10.000  90.00  90.00  90.00 P 1           1\n\
             ATOM      1  CA  GLY A   1       0.000   0.000   0.000  1.00 10.00           C  \n\
             ATOM      2  N   ALA A   2       1.000   0.000   0.000  1.00 11.00           N  \n\
             END\n",
        )
        .expect("renderer QIF molecule parses");
        let object_uid = app
            .scene_manager_mut()
            .scene_mut(created.result_scene)
            .expect("scene exists")
            .add_molecule("mol", molecule);
        let object = app
            .scene_manager_mut()
            .object_mut(object_uid)
            .expect("renderer QIF object exists");
        let trace = object.add_renderer("trace", "trace");
        let surface = object.add_renderer("molsurf", "surface");
        let symm = object.add_renderer("symm", "symm");
        let unitcell = object.add_renderer("unitcell", "unitcell");
        let labels = object.add_renderer("*namelabel", "labels");

        let (log, _) = app
            .run_script_js(&format!(
                "var trace = cuemol.getRenderer({trace}); \
                 var surface = cuemol.getRenderer({surface}); \
                 var symm = cuemol.getRenderer({symm}); \
                 var unitcell = cuemol.getRenderer({unitcell}); \
                 var labels = cuemol.getRenderer({labels}); \
                 trace.pivotatom = 'P'; \
                 surface.colormode = 'elepot'; surface.sel = cuemol.makeSel('name CA'); \
                 surface.defaultcolor = cuemol.makeColor('#102030'); \
                 surface.multi_grad.insert(0, cuemol.makeColor('green')); \
                 var homeSymmetry = symm.getXformMatrix(0).isIdent(); \
                 symm.maxop = 120; symm.extent = 25; symm.unitcell = false; \
                 var center = cuemol.Vector(); center.set3(1, 2, 3); symm.center = center; \
                 unitcell.width = 2; unitcell.color = cuemol.makeColor('yellow'); \
                 unitcell.labelcolor = cuemol.makeColor('red'); \
                 labels.maxlabel = 1; \
                 var a = labels.addLabel(1); var b = labels.addLabel(1); \
                 var c = labels.addLabel(2); var d = labels.removeLabel(1); \
                 var e = labels.removeLabel(2); var f = labels.addLabel(1); \
                 print('rendererExtra=' + trace.pivotatom + ':' + surface.colormode + ':' + \
                       surface.sel + ':' + surface.defaultcolor.r() + ':' + \
                       surface.multi_grad.size + ':' + (surface.getColorMapObj() === null) + ':' + \
                       homeSymmetry + ':' + \
                       symm.maxop + ':' + symm.extent + ':' + symm.unitcell + ':' + \
                       symm.center.x + ':' + symm.center.y + ':' + symm.center.z + ':' + \
                       unitcell.width + ':' + unitcell.color.r() + ':' + \
                       unitcell.labelcolor.r()); \
                 print('rendererLabels=' + cuemol.getClassName(labels) + ':' + \
                       a + ':' + b + ':' + c + ':' + d + ':' + e + ':' + f);",
                trace = trace.get(),
                surface = surface.get(),
                symm = symm.get(),
                unitcell = unitcell.get(),
                labels = labels.get(),
            ))
            .expect("remaining renderer QIF APIs work");
        assert!(
            log.contains(
                "rendererExtra=P:elepot:name CA:16:1:true:true:120:25:false:1:2:3:2:255:255"
            ) && log.contains("rendererLabels=NameLabelRenderer:true:false:true:false:true:true"),
            "{log:?}"
        );
        let object = app
            .scene_manager()
            .object(object_uid)
            .expect("renderer QIF object remains available");
        assert_eq!(
            object
                .renderer(trace)
                .and_then(|renderer| renderer.qsc_attr("pivotatom")),
            Some("P")
        );
        assert_eq!(
            object
                .renderer(symm)
                .and_then(|renderer| renderer.qsc_attr("center")),
            Some("(1,2,3)")
        );
        assert_eq!(
            object
                .renderer(surface)
                .and_then(|renderer| {
                    renderer
                        .qsc_children()
                        .iter()
                        .find(|child| child.tag_name() == "multi_grad")
                })
                .map(LDom2Node::child_count),
            Some(1)
        );
        assert_eq!(
            object
                .renderer(labels)
                .and_then(|renderer| renderer.qsc_children().first())
                .map(|label| label.str_attr("aid").to_string()),
            Some("A.1.CA".to_string())
        );
    }

    #[cfg(feature = "scripting")]
    #[test]
    fn run_script_js_scene_undo_redo_and_rollback_restore_state() {
        let mut app = DesktopAppState::new();
        let created = app.new_scene("before", true);
        let view_uid = created.result_view.expect("scene has a view");

        let (commit_log, _) = app
            .run_script_js(&format!(
                "scene.startUndoTxn('rename and zoom'); \
                 scene.setName('after'); cuemol.getView({}).zoom = 42; \
                 scene.commitUndoTxn(); \
                 print('commit=' + scene.isUndoable() + ':' + scene.isRedoable() + ':' + \
                       scene.getUndoSize() + ':' + scene.getRedoSize() + ':' + \
                       scene.getUndoDesc(0));",
                view_uid.get()
            ))
            .expect("undo transaction commits");
        assert!(commit_log.contains("commit=true:false:1:0:rename and zoom"));
        assert_eq!(
            app.scene_manager()
                .scene(created.result_scene)
                .expect("scene remains available")
                .name(),
            "after"
        );
        assert_eq!(
            app.command_manager()
                .view(view_uid)
                .expect("view remains available")
                .zoom(),
            42.0
        );

        let (undo_log, _) = app
            .run_script_js(
                "print('undo=' + scene.isUndoable() + ':' + scene.getUndoDesc(0) + ':' + \
                 scene.undo(0) + ':' + scene.getUndoSize() + ':' + scene.getRedoSize());",
            )
            .expect("scene undo runs");
        assert!(undo_log.contains("undo=true:rename and zoom:true:0:1"));
        assert_eq!(
            app.scene_manager()
                .scene(created.result_scene)
                .expect("scene remains available")
                .name(),
            "before"
        );
        assert_ne!(
            app.command_manager()
                .view(view_uid)
                .expect("view remains available")
                .zoom(),
            42.0
        );

        let (redo_log, _) = app
            .run_script_js(
                "print('redo=' + scene.isRedoable() + ':' + scene.getRedoDesc(0) + ':' + \
                 scene.redo(0) + ':' + scene.getUndoSize() + ':' + scene.getRedoSize());",
            )
            .expect("scene redo runs");
        assert!(redo_log.contains("redo=true:rename and zoom:true:1:0"));
        assert_eq!(
            app.scene_manager()
                .scene(created.result_scene)
                .expect("scene remains available")
                .name(),
            "after"
        );
        assert_eq!(
            app.command_manager()
                .view(view_uid)
                .expect("view remains available")
                .zoom(),
            42.0
        );

        app.run_script_js(
            "scene.startUndoTxn('rolled back'); scene.setName('discarded'); \
             scene.rollbackUndoTxn();",
        )
        .expect("scene rollback runs");
        assert_eq!(
            app.scene_manager()
                .scene(created.result_scene)
                .expect("scene remains available")
                .name(),
            "after"
        );

        let (clear_log, _) = app
            .run_script_js(
                "scene.clearUndoData(); \
                 print('clear=' + scene.isUndoable() + ':' + scene.isRedoable() + ':' + \
                       scene.getUndoSize() + ':' + scene.getRedoSize());",
            )
            .expect("undo data clears");
        assert!(clear_log.contains("clear=false:false:0:0"));
    }

    #[cfg(feature = "scripting")]
    #[test]
    fn script_scene_undo_is_scoped_to_a_non_active_receiver() {
        let mut app = DesktopAppState::new();
        let first = app.new_scene("first", true).result_scene;
        let second = app.new_scene("second", true).result_scene;
        let (commit_log, _) = app
            .run_script_js(&format!(
                "var first = cuemol.getScene({}); var second = cuemol.getScene({}); \
                 first.startUndoTxn('rename first'); first.setName('changed'); \
                 first.commitUndoTxn(); \
                 print(first.isUndoable() + ':' + second.isUndoable() + ':' + \
                       first.getUndoDesc(0));",
                first.get(),
                second.get(),
            ))
            .unwrap();
        assert_eq!(commit_log, "true:false:rename first\n");
        assert_eq!(app.scene_manager().scene(first).unwrap().name(), "changed");

        let (undo_log, _) = app
            .run_script_js(&format!(
                "var first = cuemol.getScene({}); var second = cuemol.getScene({}); \
                 print(first.undo(0) + ':' + first.isRedoable() + ':' + \
                       second.isRedoable());",
                first.get(),
                second.get(),
            ))
            .unwrap();
        assert_eq!(undo_log, "true:true:false\n");
        assert_eq!(app.scene_manager().scene(first).unwrap().name(), "first");
        assert_eq!(app.active_scene(), Some(second));
    }

    #[cfg(feature = "scripting")]
