    #[test]
    fn desktop_app_state_loads_object_and_renderer_into_active_scene() {
        let Some(root) = reference_test_data_root() else {
            return;
        };
        let mut app = DesktopAppState::new();
        let scene = app.new_scene("work", false).result_scene;
        let object = app
            .load_object_into_active_scene(root.join("1CRN.pdb"), "crambin", "pdb")
            .unwrap()
            .result_object;
        assert_eq!(app.active_scene(), Some(scene));
        assert_eq!(
            app.scene_manager()
                .scene(scene)
                .unwrap()
                .object(object)
                .unwrap()
                .mol()
                .atom_count(),
            327
        );

        let renderer = app
            .new_renderer_in_active_scene(object, "simple", "r1")
            .unwrap()
            .result_renderer;
        assert!(app
            .scene_manager()
            .scene(scene)
            .unwrap()
            .object(object)
            .unwrap()
            .renderer(renderer)
            .is_some());
        assert_eq!(app.active_render_snapshot("").unwrap().atom_count(), 327);
        assert!(
            app.renderer_summaries(object)
                .iter()
                .find(|summary| summary.uid == renderer)
                .unwrap()
                .visible
        );
        app.set_renderer_visible(object, renderer, false).unwrap();
        assert_eq!(app.active_render_snapshot("").unwrap().atom_count(), 0);
        app.set_renderer_visible(object, renderer, true).unwrap();
        assert_eq!(app.active_render_snapshot("").unwrap().atom_count(), 327);
        assert!(app.destroy_renderer_in_object(object, renderer).unwrap());
        assert_eq!(app.active_render_snapshot("").unwrap().atom_count(), 327);

        let atom = app.atom_summary(object, 0).unwrap();
        assert_eq!(atom.object_uid, object);
        assert_eq!(atom.atom_index, 0);
        assert_eq!(atom.serial, 1);
        assert_eq!(atom.selection_text, "aid 1");
    }

    #[test]
    fn surface_mesh_is_coloured_by_nearest_atom_not_flat_grey() {
        // CueMol2 MolSurfRenderer MOLFANC: each SES vertex takes its nearest atom's
        // colour-scheme colour (getColorMol). The Rust surface was a flat-grey blob
        // in all 3 GUIs; this pins the fix — a real triangle mesh whose vertices
        // carry the per-element CPK colours of the residues under them.
        let Some(root) = reference_test_data_root() else {
            return;
        };
        let mut app = DesktopAppState::new();
        app.new_scene("work", false);
        let object = app
            .load_object_into_active_scene(root.join("1CRN.pdb"), "crambin", "pdb")
            .unwrap()
            .result_object;
        // A small selection (residues 1-3 = THR/THR/CYS, exposing C/N/O/S) keeps the
        // SES build cheap while still surfacing several element colours.
        let mesh = app
            .build_surface_mesh(object, "resid 1:3", 1.0, 1.4)
            .unwrap();
        assert!(
            !mesh.indices.is_empty() && !mesh.vertices.is_empty(),
            "the SES must be a real triangle mesh"
        );
        // Quantise to bytes so we can count distinct colours — the flat-grey
        // regression would collapse this to a single colour.
        let quant = |c: f32| (c * 255.0).round() as u8;
        let distinct: std::collections::HashSet<[u8; 3]> = mesh
            .vertices
            .iter()
            .map(|v| [quant(v.color[0]), quant(v.color[1]), quant(v.color[2])])
            .collect();
        assert!(
            distinct.len() > 1,
            "surface must be multi-coloured (nearest-atom), not flat grey; got {distinct:?}"
        );
        // The specific CPK colours of exposed oxygen and carbon must appear, and the
        // former uniform grey (0.76,0.79,0.84) must be gone.
        let has = |target: [f32; 3]| {
            mesh.vertices
                .iter()
                .any(|v| (0..3).all(|k| (v.color[k] - target[k]).abs() < 0.02))
        };
        assert!(
            has([0.92, 0.12, 0.12]),
            "oxygen-red vertices expected on the SES"
        );
        assert!(
            has([0.38, 0.38, 0.38]),
            "carbon-grey vertices expected on the SES"
        );
        assert!(
            !has([0.76, 0.79, 0.84]),
            "no vertex should keep the old flat-grey surface colour"
        );
    }

    #[test]
    fn surface_vertex_atom_id_takes_precedence_over_nearest_position() {
        let mut app = DesktopAppState::new();
        let scene_uid = app.new_scene("surface", false).result_scene;
        let molecule = cuemol_molstr::read_pdb_str(
            "ATOM      1  N   GLY A   1       0.000   0.000   0.000  1.00 10.00           N\n\
             ATOM      2  O   GLY A   1      10.000   0.000   0.000  1.00 10.00           O\n",
        )
        .unwrap();
        let object_uid = app
            .scene_manager_mut()
            .scene_mut(scene_uid)
            .unwrap()
            .add_molecule("mol", molecule);
        let object = app.scene_manager().object(object_uid).unwrap();
        let mut mesh = cuemol_surface::SurfaceMesh::new();
        for position in [
            Vector4::new3(0.0, 0.0, 0.0),
            Vector4::new3(0.1, 0.0, 0.0),
            Vector4::new3(0.0, 0.1, 0.0),
        ] {
            mesh.push_vertex(cuemol_surface::SurfaceVertex::with_info(
                position,
                Vector4::new3(0.0, 0.0, 1.0),
                2,
            ));
        }
        mesh.push_triangle([0, 1, 2]);

        let rendered = surface_mesh_render_mesh(object, &Selector::All, &mesh);
        assert!(rendered.vertices.iter().all(|vertex| {
            [0.92, 0.12, 0.12]
                .iter()
                .enumerate()
                .all(|(channel, expected)| (vertex.color[channel] - expected).abs() < 0.02)
        }));
    }

    #[test]
    fn load_mesh_surface_reads_an_obj_into_a_flat_render_mesh() {
        // The import path is molecule-independent: an OBJ (here written by hand,
        // the same shape the surface crate's OBJ writer emits) loads into a
        // RenderMesh with matching counts and the flat standalone-surface colour,
        // ready for the existing surface toggle. No scene / molecule required.
        let path = std::env::temp_dir().join("cuemol_load_mesh_surface_test.obj");
        std::fs::write(
            &path,
            "o t\nv 0 0 0\nv 1 0 0\nv 0 1 0\nvn 0 0 1\nvn 0 0 1\nvn 0 0 1\nf 1//1 2//2 3//3\n",
        )
        .unwrap();
        let app = DesktopAppState::new();
        let mesh = app.load_mesh_surface_file(path.to_str().unwrap()).unwrap();
        assert_eq!(mesh.vertices.len(), 3);
        assert_eq!(mesh.indices.len(), 3, "one triangle -> three indices");
        assert_eq!(mesh.vertices[0].color, [0.45, 0.65, 0.95, 1.0]);
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn qsc_with_an_obj_text_surface_loads_as_a_display_mesh() {
        // End-to-end library slice: a `.qsc` carrying an OBJ-text MolSurf object loads,
        // and the shared render snapshot contains its flat mesh. The `.qsc` base is
        // the real writer's output with an OBJ surface + datachunk spliced in.
        let mut builder = MolSceneManager::new();
        let bscene = builder.new_scene("s");
        let mol = cuemol_molstr::read_pdb_str(
            "ATOM      1  CA  ALA A   1       0.000   0.000   0.000  1.00  0.00\n",
        )
        .unwrap();
        builder.scene_mut(bscene).unwrap().add_molecule("mol1", mol);
        let mut qsc = builder.scene(bscene).unwrap().write_qsc_string();
        let surf = "\t<object type=\"MolSurf\" name=\"surf1\" src=\"datachunk:90000\" srctype=\"obj\">\n\t</object>\n</scene>";
        qsc = qsc.replace("</scene>", surf);
        qsc.push_str(
            "\n==========START datachunk:90000==========\nv 0 0 0\nv 1 0 0\nv 0 1 0\nf 1 2 3\n==========END datachunk:90000==========\n",
        );
        let path = std::env::temp_dir().join("cuemol_core_qsc_surface_test.qsc");
        std::fs::write(&path, &qsc).unwrap();

        let mut app = DesktopAppState::new();
        app.load_qsc_file(&path).unwrap();
        let meshes = app.active_scene_surface_meshes();
        assert_eq!(
            meshes.len(),
            1,
            "the OBJ surface object becomes one render mesh"
        );
        assert_eq!(meshes[0].vertices.len(), 3);
        assert_eq!(meshes[0].indices.len(), 3, "one triangle -> three indices");
        assert_eq!(meshes[0].vertices[0].color, [0.45, 0.65, 0.95, 1.0]);
        let snapshot = app.active_render_snapshot("").unwrap();
        assert_eq!(snapshot.mesh_count(), 1);
        assert_eq!(snapshot.meshes[0], meshes[0]);
        let _ = std::fs::remove_file(&path);
    }

